CREATE OR REPLACE FUNCTION public.fn_get_all_invoices(p_tenant_id uuid DEFAULT NULL::uuid, p_organization_id uuid DEFAULT NULL::uuid, p_status character varying DEFAULT NULL::character varying)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, invoice_number character varying, billing_period character varying, subtotal numeric, discount_amount numeric, tax_amount numeric, total_amount numeric, amount_paid numeric, currency character varying, status character varying, issue_date timestamp with time zone, due_date timestamp with time zone, paid_at timestamp with time zone, published_at timestamp with time zone, published_by character varying, voided_at timestamp with time zone, voided_by character varying, void_reason text, created_by character varying, description text, notes text, payment_instructions text, billing_contact_email character varying, document_storage_key character varying, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE sql  STABLE AS $function$     SELECT          id, tenant_id, organization_id, invoice_number, billing_period,         subtotal, discount_amount, tax_amount, total_amount, amount_paid,         currency, status, issue_date, due_date, paid_at, published_at,         published_by, voided_at, voided_by, void_reason, created_by,         description, notes, payment_instructions, billing_contact_email,         document_storage_key, created_at, updated_at     FROM invoices     WHERE (p_tenant_id IS NULL OR tenant_id = p_tenant_id)       AND (p_organization_id IS NULL OR organization_id = p_organization_id)       AND (p_status IS NULL OR status = p_status)     ORDER BY issue_date DESC, created_at DESC; $function$ ;
